document.addEventListener('DOMContentLoaded', function() {
    const chartDiv = document.getElementById('chart-container');
    const width = chartDiv.clientWidth;
    const height = chartDiv.clientHeight;

    const svg = d3.select('#chart-container')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    const tooltip = d3.select('#tooltip');

    let selectedTicker = null;

    d3.csv('data/stock-descriptions.csv').then(data => {
        data.forEach(d => {
            d.marketCap = d.marketCap ? +d.marketCap : 0;
        });

        const sectors = Array.from(new Set(data.map(d => d.sector)));
        const colorScale = d3.scaleOrdinal()
            .domain(sectors)
            .range(d3.schemeCategory10);

        const maxCap = d3.max(data, d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain([0, maxCap])
            .range([10, 50]);

        data.forEach(d => {
            d.radius = d.marketCap === 0 ? 15 : radiusScale(d.marketCap);
        });

        const sectorCenters = {};
        const angleStep = (2 * Math.PI) / sectors.length;
        const orbitRadius = Math.min(width, height) / 3;

        sectors.forEach((sector, i) => {
            sectorCenters[sector] = {
                x: width / 2 + orbitRadius * Math.cos(i * angleStep),
                y: height / 2 + orbitRadius * Math.sin(i * angleStep)
            };
        });

        const simulation = d3.forceSimulation(data)
            .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.15))
            .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.15))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .force('collide', d3.forceCollide(d => d.radius + 2))
            .on('tick', ticked);

        const bubbles = svg.selectAll('.bubble-group')
            .data(data)
            .enter()
            .append('g')
            .attr('class', 'bubble-group')
            .on('mouseover', (event, d) => {
                if (d.marketCap > 0) {
                    tooltip.style('display', 'block')
                        .html(`<strong>${d.ticker}</strong><br>${d['full name']}<br>${d.sector}`);
                }
            })
            .on('mousemove', (event) => {
                tooltip.style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px');
            })
            .on('mouseout', () => {
                tooltip.style('display', 'none');
            })
            .on('click', function(event, d) {
                highlightElement(d.ticker);
            });

        bubbles.append('circle')
            .attr('class', 'bubble')
            .attr('id', d => `bubble-${d.ticker}`)
            .attr('r', d => d.radius)
            .attr('fill', d => colorScale(d.sector));

        bubbles.append('text')
            .attr('class', 'label')
            .text(d => d.ticker)
            .attr('dy', '.3em');

        function ticked() {
            bubbles.attr('transform', d => {
                // Keep within bounds
                d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
                d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
                return `translate(${d.x},${d.y})`;
            });
        }

        const legendContainer = d3.select('#chart-container')
            .append('div')
            .attr('class', 'legend');

        sectors.forEach(sector => {
            const item = legendContainer.append('div').attr('class', 'legend-item');
            item.append('div')
                .attr('class', 'legend-color')
                .style('background-color', colorScale(sector));
            item.append('span').text(sector);
        });

        const tableBody = d3.select('#stock-table tbody');
        const rows = tableBody.selectAll('tr')
            .data(data)
            .enter()
            .append('tr')
            .attr('id', d => `row-${d.ticker}`)
            .on('click', function(event, d) {
                highlightElement(d.ticker);
            });

        rows.append('td').text(d => d.ticker);
        rows.append('td').text(d => d['full name']);
        rows.append('td').text(d => d.sector);
        rows.append('td').text(d => formatMarketCap(d.marketCap));

        function highlightElement(ticker) {
            selectedTicker = ticker;
            d3.selectAll('.bubble').classed('highlighted', false);
            d3.selectAll('tr').classed('highlighted', false);

            d3.select(`#bubble-${ticker}`).classed('highlighted', true);
            const row = d3.select(`#row-${ticker}`);
            row.classed('highlighted', true);

            const tableContainer = document.getElementById('table-container');
            const rowElement = document.getElementById(`row-${ticker}`);
            tableContainer.scrollTo({
                top: rowElement.offsetTop - tableContainer.offsetTop,
                behavior: 'smooth'
            });

            updatePriceChart(ticker);
        }

        function formatMarketCap(d) {
            if (!d || d === 0) return "N/A";
            if (d >= 1e12) return (d / 1e12).toFixed(2) + "T";
            if (d >= 1e9) return (d / 1e9).toFixed(2) + "B";
            if (d >= 1e6) return (d / 1e6).toFixed(2) + "M";
            return d.toLocaleString();
        }

        // Price Chart Logic
        const priceContainer = d3.select('#price-history-container');
        const priceWidth = document.getElementById('price-history-container').clientWidth - 40;
        const priceHeight = document.getElementById('price-history-container').clientHeight - 60;

        const priceSvg = priceContainer.append('svg')
            .attr('width', priceWidth + 40)
            .attr('height', priceHeight + 40)
            .append('g')
            .attr('transform', 'translate(40, 20)');

        function updatePriceChart(ticker) {
            d3.csv(`data/indiv-stock/${ticker}.csv`).then(priceData => {
                priceData.forEach(p => {
                    p.Date = new Date(p.Date);
                    p.Close = +p.Close;
                });

                // Sort by date and take last 250 points for better visualization
                priceData.sort((a, b) => a.Date - b.Date);
                if (priceData.length > 250) priceData = priceData.slice(-250);

                const x = d3.scaleTime()
                    .domain(d3.extent(priceData, p => p.Date))
                    .range([0, priceWidth]);

                const y = d3.scaleLinear()
                    .domain([d3.min(priceData, p => p.Close) * 0.95, d3.max(priceData, p => p.Close) * 1.05])
                    .range([priceHeight, 0]);

                priceSvg.selectAll('*').remove();

                priceSvg.append('g')
                    .attr('transform', `translate(0,${priceHeight})`)
                    .call(d3.axisBottom(x).ticks(6));

                priceSvg.append('g')
                    .call(d3.axisLeft(y));

                priceSvg.append('path')
                    .datum(priceData)
                    .attr('fill', 'none')
                    .attr('stroke', '#007bff')
                    .attr('stroke-width', 2)
                    .attr('d', d3.line()
                        .x(p => x(p.Date))
                        .y(p => y(p.Close))
                    );

                priceContainer.select('.price-chart-title').text(`Price History: ${ticker}`);
            }).catch(err => {
                console.error("Could not load price data for", ticker, err);
                priceSvg.selectAll('*').remove();
                priceContainer.select('.price-chart-title').text(`Price History: ${ticker} (Data not found)`);
            });
        }

        // Select first stock by default
        if (data.length > 0) highlightElement(data[0].ticker);
    });
});
